import zipfile
import xml.etree.ElementTree as ET

NS = {'m': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
path = 'budget.xlsx'

with zipfile.ZipFile(path) as z:
    names = z.namelist()
    print("ZIP contents:", names)

    wb = ET.fromstring(z.read('xl/workbook.xml'))
    sheets = [(s.get('name'), s.get('sheetId'), s.get('{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id'))
              for s in wb.find('m:sheets', NS)]
    print("Sheets:", sheets)

    # shared strings
    shared = []
    if 'xl/sharedStrings.xml' in names:
        ss = ET.fromstring(z.read('xl/sharedStrings.xml'))
        for si in ss.findall('m:si', NS):
            text = ''.join(t.text or '' for t in si.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t'))
            shared.append(text)

    for i, (name, sid, rid) in enumerate(sheets, start=1):
        fname = f'xl/worksheets/sheet{i}.xml'
        if fname not in names:
            # resolve via rels
            rels = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
            target = None
            for rel in rels:
                if rel.get('Id') == rid:
                    target = rel.get('Target')
                    break
            fname = 'xl/' + target.lstrip('/')
        ws = ET.fromstring(z.read(fname))
        print(f"\n--- Sheet: {name} ---")
        rows = []
        for row in ws.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}row'):
            cells = {}
            for c in row:
                ref = c.get('r')
                t = c.get('t')
                v = c.find('m:v', NS)
                isel = c.find('m:is', NS)
                if t == 's' and v is not None:
                    val = shared[int(v.text)]
                elif t == 'inlineStr' and isel is not None:
                    val = ''.join(x.text or '' for x in isel.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t'))
                elif v is not None:
                    val = v.text
                else:
                    val = None
                if ref:
                    cells[ref] = val
            if cells:
                rows.append(cells)
        # print as a table
        all_refs = []
        for r in rows:
            for ref in r:
                if ref not in all_refs:
                    all_refs.append(ref)
        all_refs.sort(key=lambda x: (int(''.join(ch for ch in x if ch.isdigit()) or 0),
                                     ''.join(ch for ch in x if ch.isalpha())))
        header = [ref for ref in all_refs]
        print('\t'.join(header))
        for r in rows:
            print('\t'.join(str(r.get(ref, '')) for ref in all_refs))

